// x87, each instruction run on known inputs and checked byte for byte, on lambda for x86-64. Written by x87.py,
// whose answers are what an x87 stores; the kernels README says how to build it.

typedef unsigned char u8;
typedef long long i64;
#ifdef __APPLE__
/* Also an x86-64 macOS program, to check the answers on a real x87 (macOS's own x86-64 translation). */
#include <stdlib.h>
#include <unistd.h>
static void say(const char *s) { int n = 0; while (s[n]) n++; write(1, s, n); }
static void finish(int failures) { exit(failures); }
#else
static i64 sys(i64 n, i64 a, i64 b, i64 c) {
    i64 ret;
    __asm__ volatile("syscall" : "=a"(ret) : "a"(n), "D"(a), "S"(b), "d"(c) : "rcx", "r11", "memory");
    return ret;
}
static void say(const char *s) { int n = 0; while (s[n]) n++; sys(1, 1, (i64)s, n); }
static void finish(int failures) { sys(231, failures, 0, 0); }
#endif
static int failures;
static void check(int ok, const char *what) {
    say(ok ? "ok      " : "FAILED  ");
    say(what);
    say("\n");
    if (!ok) failures++;
}
/* Bytes `care` marks are compared; the rest of the 64 must still be 0xaa, as they were before. */
static int same(const u8 *out, const u8 *want, const u8 *care, int n) {
    for (int i = 0; i < 64; i++) {
        if (i >= n) { if (out[i] != 0xaa) return 0; }
        else if (care[i] && out[i] != want[i]) return 0;
    }
    return 1;
}

static void case0(u8 *out, const u8 *in) {
    __asm__ volatile("mov %0, %%rsi\n mov %1, %%rdi\n .byte 0xd9, 0x7e, 0x00"
                     :: "r"(out), "r"(in) : "rax", "rsi", "rdi", "memory", "cc", "st", "st(1)", "st(2)",
                       "st(3)", "st(4)", "st(5)", "st(6)", "st(7)");
}
